def star_hash_balance(s):
    star_count = 0
    hash_count = 0

    for char in s:
        if char == '*':
            star_count += 1
        elif char == '#':
            hash_count += 1

    return star_count - hash_count

# Input
s = input()
print(star_hash_balance(s))

def count_greater_brute(arr, n):
    count = 1  # first element always counted

    for i in range(1, n):
        is_greater = True
        for j in range(i):
            if arr[j] >= arr[i]:
                is_greater = False
                break
        if is_greater:
            count += 1

    return count

# Input
n = int(input())
arr = list(map(int, input().split()))
print(count_greater_brute(arr, n))

def odd_balloon_brute(balloons, n):
    checked = set()

    for b in balloons:
        if b in checked:
            continue
        checked.add(b)
        count = 0
        for x in balloons:
            if x == b:
                count += 1
        if count % 2 != 0:
            return b

    return "All are even"

# Input
n = int(input())
balloons = input().split()
print(odd_balloon_brute(balloons, n))

def min_moves_brute(n, a, b):
    if a == b:
        return 0

    # Collect differing characters from A and target chars from B
    res = ""   # chars in A at differing positions
    res2 = ""  # chars in B at differing positions

    for i in range(n):
        if a[i] != b[i]:
            res += a[i]
            res2 += b[i]

    # Check feasibility: each target char in B must exist in A
    for ch in set(res2):
        if ch not in a:
            return -1

    # Number of operations = number of unique target characters
    return len(set(res2))

# Input
n = int(input())
a = input()
b = input()
print(min_moves_brute(n, a, b))

